import React from 'react';

const Navbar = () => (
  <nav className="bg-gray-800 text-white p-4 sticky top-0 z-10">
    <div className="container mx-auto flex justify-between items-center">
      <h1 className="text-xl font-bold">Muhammad Shahan</h1>
      <ul className="flex space-x-4 list-none"> {/* Added list-none to prevent default list styling */}
        <li><a href="#about" className="hover:text-gray-300">About</a></li>
        <li><a href="#experience" className="hover:text-gray-300">Experience</a></li>
        <li><a href="#skills" className="hover:text-gray-300">Skills</a></li>
        <li><a href="#projects" className="hover:text-gray-300">Projects</a></li>
        <li><a href="#contact" className="hover:text-gray-300">Contact</a></li>
      </ul>
    </div>
  </nav>
);

export default Navbar;
